const parseDMS = (dmsString) => {
  const re = /(\d+)°(\d+)′(\d+)″/;
  const m = dmsString.match(re);
  if (!m) return { deg: "", min: "", sec: "" };
  return { deg: m[1], min: m[2], sec: m[3] };
};

export {parseDMS}
